-- Repeatable migration: append the July 2026 training block (weeks 10-13).
--
-- Source: 'Logan PL (1).xlsx', sheet '762026' (7/6/2026). The block is
-- appended onto the existing program seeded by R__seed_dev_data.sql
-- ('Logan PL - May/June 2026 Block'). The owner user and every referenced
-- exercise are already inserted there; this file only adds the new weeks,
-- days, exercises, and set targets. Its description sorts after
-- 'seed_dev_data', so Flyway applies those parent rows first.
--
-- Calendar alignment: the app derives each day's date as
-- start_date + (sequence - 1) * 7 + dayIndex (fixed 7 days/week). The program
-- starts 2026-05-04, so the training block must sit at sequences 10-13 to make
-- week 1 day 1 land on 2026-07-06. Sequence 9 is a full rest week (a deload
-- taken the week before this block) that supplies the +7-day offset.
--
-- Encoding matches the base seed: loads are lb converted to kg at 0.45359237
-- (rounded to 2dp); an RPE number in the Intensity column becomes
-- prescribed_rpe (plus a Load Cap sets both prescribed_load_kg and
-- cap_load_kg); a bare weight string ('320lb') becomes prescribed_load_kg
-- only; a negative value becomes a '-N%' intensity_text; RIR strings pass
-- through verbatim. Sheet Day 2 and Day 4 carry headers but no prescribed
-- work (the coach note adds a recovery day) so they are modelled as rest
-- days with no exercises.
--
-- Idempotent: deterministic UUIDs plus `on conflict (id) do nothing`.

set search_path to fitlytics, public;

-- 1. Rest week (sequence 9) + training weeks 10-13 (appended to the May/June
--    program). The rest week is the deload taken before this block; it shifts
--    week 10 day 1 onto 2026-07-06.
on conflict (id) do nothing;

-- 1b. Rest week days: seven rest days so the deload week is self-describing
--     (the day selector would also auto-fill these, but materialize them for
--     completeness alongside the other weeks).
on conflict (id) do nothing;

-- 2. Days per week: Day 1/3/5 train, Day 2/4 rest
on conflict (id) do nothing;

-- 3. Program exercises (training days only)
on conflict (id) do nothing;

-- 4. Set groups (one per spreadsheet row within an exercise)
on conflict (id) do nothing;

-- 5. Sets (Sets count -> N identical rows; values from each week's columns)
on conflict (id) do nothing;

-- 6. Coach note capturing the block rationale from the sheet header
update program_days set notes = E'Block focus (from 762026): developing back pain / bench stalling.
Bench volume reduced by one set per week.
Added a recovery day - Day 2 and Day 4 are rest.
Weekly top-set progression: Squat +5, Bench +0, Deadlift +10.'
  where id = 'ae3af73d-e335-5b2b-9926-6d523d96cb16' and notes is null;

